#!/usr/bin/env python3
"""Revision-scoped lease census and causal application service census.

Discovery evidence is lease scoped: internal clean sets hold low targets that
positively echoed themselves, external clean sets hold other responders, and a
canary self echo quarantines its whole lease.  An application row only counts
when its lease is usable, its target holds a clean role, and that role's
earliest causal witness is not later than the row's event.
"""
from common import addresses
from ledger import Ledger
from protocols import cached_signature

ICMP_ECHO, ICMP_ERROR, ICMP_TIMEOUT = 0, 1, 2
APP_OPEN, APP_CLOSED, APP_TIMEOUT = 0, 1, 2
ROW_ICMP, ROW_APP, ROW_TOMB = 0, 1, 2
ROLE_INTERNAL, ROLE_EXTERNAL = 0, 1

EMPTY = frozenset()


def _better(table, address, moment):
    previous = table.get(address)
    if previous is None or moment < previous:
        table[address] = moment


def _discovery(live, order, alias, internal, external, witness_in, witness_out,
               applications):
    for detail in live:
        kind = detail[0]
        if kind == ROW_ICMP:
            _, lease, event, target, responder, result, is_canary = detail
            if lease not in internal:
                continue
            if is_canary:
                # Only a positive canary self echo marks the whole lease aliased.
                if result == ICMP_ECHO and responder == target:
                    alias.add(lease)
                continue
            if result == ICMP_TIMEOUT:
                continue
            if result == ICMP_ECHO and responder == target:
                internal[lease].add(responder)
                _better(witness_in[lease], responder, event)
            else:
                external[lease].add(responder)
                _better(witness_out[lease], responder, event)
        elif kind == ROW_APP:
            applications.append(detail)


def _apply_groups(applications, state, clean_in, clean_out, witness_in,
                  witness_out, kinds):
    groups = {}
    unbound = 0
    for detail in applications:
        _, lease, event, target, service, attempt, result, payload = detail
        role = -1
        if state[lease] == 'usable':
            if target in clean_in[lease]:
                role = ROLE_INTERNAL
                witness = witness_in[lease].get(target)
            elif target in clean_out[lease]:
                role = ROLE_EXTERNAL
                witness = witness_out[lease].get(target)
            else:
                witness = None
            if witness is not None and witness <= event:
                key = (lease, target, service)
                group = groups.get(key)
                if group is None:
                    group = groups[key] = [attempt, role, {}, 0, 0, 0]
                elif attempt > group[0]:
                    group[0] = attempt
                    group[2] = {}
                    group[3] = group[4] = group[5] = 0
                if attempt == group[0]:
                    if result == APP_OPEN:
                        parsed = cached_signature(kinds[service], payload)
                        if parsed is None:
                            group[3] += 1   # malformed latest-attempt identity
                        else:
                            group[2][parsed] = group[2].get(parsed, 0) + 1
                    elif result == APP_CLOSED:
                        group[4] += 1
                    else:
                        group[5] += 1
                continue
        unbound += 1
    return groups, unbound


def _reports(groups, service_order):
    """Fold group decisions into per lease/service role subsets."""
    reports = {}
    for (lease, target, service), group in groups.items():
        report = reports.get(lease)
        if report is None:
            report = reports[lease] = {name: [set(), set(), set(), set(), 0]
                                       for name in service_order}
        entry = report[service]
        bad, closed, timeouts, signatures = group[2], group[3], group[4], group[5]
        # group[2]=signatures, group[3]=bad, group[4]=closed, group[5]=timeout
        total = len(signatures) + 0
        entry[4] += bad
        if closed and closed == total_rows(group):
            status = 1
        elif bad or timeouts or closed or len(signatures) != 1:
            status = -1
        else:
            status = 0
        if status < 0:
            continue
        index = 0 if group[1] == ROLE_INTERNAL else 2
        report[service][index + status].add(target)
    return reports


def total_rows(group):
    return group[3] + group[4] + group[5] + sum(group[2].values())


def build(context, records, low):
    """Return (snapshots, request activity booleans keyed by request id)."""
    leases = context['leases']
    kinds = context['services']
    service_order = context['service_order']
    ledger = Ledger(records)
    order = sorted(leases)
    by_query = {moment: [] for moment in context['queries']}
    for row in context['requests'].values():
        by_query[row['at']].append(row)

    snapshots = []
    activity = {}
    for moment in context['queries']:
        counts, live = ledger.at(moment)
        internal = {name: set() for name in order}
        external = {name: set() for name in order}
        witness_in = {name: {} for name in order}
        witness_out = {name: {} for name in order}
        alias = set()
        applications = []
        _discovery(live, order, alias, internal, external, witness_in,
                   witness_out, applications)

        state = {}
        clean_in = {}
        clean_out = {}
        clashes = {}
        for name in order:
            row = leases[name]
            if not (row['start'] <= moment < row['end']):
                state[name] = 'inactive'
                clean_in[name] = clean_out[name] = clashes[name] = EMPTY
                continue
            clash = internal[name] & external[name]
            clashes[name] = clash
            if name in alias:
                state[name] = 'alias'
                clean_in[name] = clean_out[name] = EMPTY
            elif clash:
                state[name] = 'conflict'
                clean_in[name] = clean_out[name] = EMPTY
            else:
                state[name] = 'usable'
                clean_in[name] = internal[name]
                clean_out[name] = external[name]

        groups, unbound = _apply_groups(applications, state, clean_in, clean_out,
                                        witness_in, witness_out, kinds)
        reports = _reports(groups, service_order)

        lease_rows = []
        for name in order:
            status = state[name]
            inside = clean_in[name]
            outside = clean_out[name]
            if status == 'usable':
                unresolved = low[name] - inside - outside
            elif status == 'inactive':
                unresolved = EMPTY
            else:
                unresolved = low[name]
            report = reports.get(name)
            services_out = []
            for index, service in enumerate(service_order):
                if report is None:
                    entry = ([], [], [], [], 0)
                    only = EMPTY
                else:
                    entry = report[service]
                    only = entry[0] if outside and len(entry[3]) == len(outside) \
                        else EMPTY
                services_out.append({
                    'id': service,
                    'internal_open': addresses(entry[0]),
                    'internal_closed': addresses(entry[1]),
                    'external_open': addresses(entry[2]),
                    'external_closed': addresses(entry[3]),
                    'internal_only': addresses(only),
                    'protocol_errors': entry[4]})
            lease_rows.append({'lease': name, 'state': status,
                               'conflicts': addresses(clashes[name]),
                               'internal': addresses(inside),
                               'external': addresses(outside),
                               'unresolved': addresses(unresolved),
                               'services': services_out})

        for row in by_query[moment]:
            name = row['lease']
            target = row['address']
            yes = False
            if state[name] == 'usable' and target in clean_in[name]:
                report = reports.get(name)
                if report is not None:
                    entry = report[row['service']]
                    yes = target not in entry[0] and target not in entry[1]
                else:
                    yes = True
            activity[row['id']] = yes

        snapshots.append({'at': moment, 'ledger': counts,
                          'unbound_applications': unbound, 'leases': lease_rows})
    return snapshots, activity
